def sumSquaresN(n: int) -> int:
    if n < 1:
        return 0
    return n * (n + 1) * (2 * n + 1) // 6

def main() -> None:
    test_cases = [
        (-5, 0),
        (0, 0),
        (1, 1),
        (5, 55),
        (10, 385),
        (100, 338350),
        (1000, 333833500),
    ]

    for val, expected in test_cases:
        result = sumSquaresN(val)
        print(result)
        assert result == expected, f"Failed for n={val}: got {result}, expected {expected}"

if __name__ == "__main__":
    main()

