import java.util.*;

public class Solution {
    public static long sumSquaresN(long n) {
        if (n < 1) {
            return 0L;
        }
        return n * (n + 1) * (2 * n + 1) / 6;
    }

    public static void main(String[] args) {
        // Test case 1: n = 0 (edge case, should return 0)
        System.out.println(sumSquaresN(0));

        // Test case 2: n = 1 (smallest positive)
        System.out.println(sumSquaresN(1));

        // Test case 3: n = 5 (1+4+9+16+25 = 55)
        System.out.println(sumSquaresN(5));

        // Test case 4: n = 10 (known formula result 385)
        System.out.println(sumSquaresN(10));

        // Test case 5: n = 100 (large value, verify formula works)
        System.out.println(sumSquaresN(100));

        // Test case 6: n = -5 (negative, should return 0)
        System.out.println(sumSquaresN(-5));

        // Test case 7: n = 20 (additional normal case)
        System.out.println(sumSquaresN(20));
    }
}
